<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use App\Services\AuditService;
class InferredDataController extends Controller {
    private $fields=['stem_background','central_party_school','provincial_party_school','national_academy_of_governance','military_academy','worked_abroad','location','time_period','diplomatic_posting','foreign_languages','foreign_trips_post_2022','first_province','total_appointments','total_working_years_party_member','total_provinces_served','local_government_experience','provincial_government_experience','provincial_party_experience','central_government_experience','central_party_experience','soe_experience','pla_experience','economic_policy_experience','financial_policy_experience','technology_policy_experience','foreign_affairs_experience','propaganda_experience','party_organization_experience','ccdi_experience','internal_security_experience','agriculture_rural_affairs','industrial_policy_experience','pla_service_experience','central_military_commission_experience','defence_industry_experience','coastal_experience','inland_experience','border_province_experience','minority_region_experience','municipality_experience','years_to_county','years_to_prefecture','years_to_province','years_to_center','years_to_politburo','years_to_psc','year_entered_politburo','year_entered_psc','served_in_secretariat','served_in_ccdi_leadership','served_in_npc_leadership','served_in_cppcc_leadership','member_of_cmc','xi_proximity_score','factional_affiliation_score','promotion_probability','retirement_probability','successor_potential'];
    private function leader($id){return DB::table('leaders')->where('leader_id',$id)->firstOrFail();}
    public function edit($leaderId){$leader=$this->leader($leaderId);$inferred=DB::table('inferred_data')->where('leader_id',$leaderId)->first();return view('admin.inferred.form',compact('leader','inferred'));}
    public function update(Request $r,$leaderId){$this->leader($leaderId);$d=$r->validate(array_fill_keys($this->fields,'nullable'));$old=(array)DB::table('inferred_data')->where('leader_id',$leaderId)->first();DB::table('inferred_data')->updateOrInsert(['leader_id'=>$leaderId],$d);AuditService::log('updated','inferred_data',$leaderId,$old,$d,'Inferred data saved');return redirect()->route('admin.leaders.show',$leaderId)->with('success','Inferred data saved.');}
    public function destroy($leaderId){$this->leader($leaderId);$old=(array)DB::table('inferred_data')->where('leader_id',$leaderId)->first();DB::table('inferred_data')->where('leader_id',$leaderId)->delete();AuditService::log('deleted','inferred_data',$leaderId,$old,null,'Inferred data deleted');return back()->with('success','Inferred data deleted.');}
}
